function maxDepth(root: TreeNode | null): number {
  // Пустое дерево имеет глубину 0
  if (root === null) {
    return 0;
  }

  // Глубина дерева = 1 (сам узел) + глубина более глубокого поддерева
  return 1 + Math.max(maxDepth(root.left), maxDepth(root.right));
}

// Время: O(n) — каждый узел посещается один раз
// Память: O(h) — глубина стека рекурсии равна высоте дерева
